#include <HX711.h>

const int DT_PIN = {{DT}};
const int SCK_PIN = {{SCK}};
HX711 scale;

void setup() {
  Serial.begin(115200);
  scale.begin(DT_PIN, SCK_PIN);
}

void loop() {
  if (scale.is_ready()) {
    Serial.print("Raw reading: ");
    Serial.println(scale.read());
  } else {
    Serial.println("HX711 not ready");
  }
  delay(500);
}
